// Generated by `just generate` from `src/plugins/claudetto/slices/policy/domain/discover.ts`. Edit the source and run `just generate`.
// The discovery of the policy files of a repository, by a fixed list of file names.
// It reads no file content to decide what a file is: a name either is in the list or is not.
// A `Reader` gives the same view of a checkout on disk and of a repository on GitHub.

import { FILES_MAX } from "../limits.ts";

/** An entry of a folder. */
export type Entry = { name: string; kind: "file" | "dir" | "other" };

/** Lists a folder and reads a file. A folder or a file that is absent gives `[]` or `undefined`, and a real failure rejects. */
export interface Reader {
  list(dir: string): Promise<Entry[]>;
  read(path: string): Promise<string | undefined>;
}

/** One policy file: its path under the source, and its text. */
export type PolicyFile = { path: string; text: string };

/** What a discovery found, and what it could not read. */
export type Found = { files: PolicyFile[]; unread: string[] };

/** A name in the list: exact, a prefix, or one with the word `AI` or `LLM` in it. The compare is case-insensitive. */
type Name = { name: string; prefix: boolean; ai?: boolean };

const exact = (name: string): Name => ({ name, prefix: false });
const prefix = (name: string): Name => ({ name, prefix: true });
/** A file name with a part `AI` or `LLM` when it is split at each character that is not a letter or a digit, or a part such as `AIAgreement`. It reads the name of the file only. */
const AI_NAME: Name = { name: "", prefix: false, ai: true };

const hasAiPart = (file: string): boolean =>
  file
    .split(/[^A-Za-z0-9]+/)
    .some(
      (part) =>
        ["ai", "llm", "llms"].includes(part.toLowerCase()) ||
        /^AI[A-Z][a-z]/.test(part),
    );

/** The file names to find in the root folder. */
const ROOT: Name[] = [
  exact("AGENTS.md"),
  exact("CLAUDE.md"),
  exact("GEMINI.md"),
  exact(".cursorrules"),
  AI_NAME,
  prefix("CONTRIBUTING"),
  prefix("CONTRIBUTION"),
  prefix("CONVENTIONS"),
  prefix("HACKING"),
  prefix("AI_POLICY"),
  prefix("AI-POLICY"),
  prefix("CODE_OF_CONDUCT"),
  prefix("README"),
  prefix("PULL_REQUEST_TEMPLATE"),
];

/** The file names to find in `.github/`. */
const GITHUB: Name[] = [
  exact("AGENTS.md"),
  exact("copilot-instructions.md"),
  AI_NAME,
  prefix("CONTRIBUTING"),
  prefix("AI_POLICY"),
  prefix("AI-POLICY"),
  prefix("CODE_OF_CONDUCT"),
  prefix("README"),
  prefix("PULL_REQUEST_TEMPLATE"),
];

/** The folders to list, with the file names to find in each. */
const FOLDERS: [string, Name[]][] = [
  ["", ROOT],
  [".github", GITHUB],
  [".claude", [exact("CLAUDE.md")]],
  [
    "docs",
    [
      AI_NAME,
      prefix("CONTRIBUTING"),
      prefix("HACKING"),
      prefix("SUBMITTINGPATCHES"),
      prefix("AI_POLICY"),
      prefix("AI-POLICY"),
    ],
  ],
  ["doc", [AI_NAME, prefix("CONTRIBUTING"), prefix("HACKING")]],
  ["policies", [AI_NAME]],
  ["docs/guidelines", [AI_NAME]],
  ["doc/internals", [AI_NAME]],
  ["doc/contribute", [AI_NAME]],
];

/** The folders of which every file is a policy file. */
const TEMPLATE_FOLDERS = [
  ".github/PULL_REQUEST_TEMPLATE",
  ".github/ISSUE_TEMPLATE",
  ".cursor/rules",
  ".gitlab/merge_request_templates",
  ".gitlab/issue_templates",
  "CONTRIBUTING.d",
];

const matches = (file: string, names: Name[]): boolean => {
  const low = file.toLowerCase();
  return names.some((n) => {
    const want = n.name.toLowerCase();
    if (n.ai === true) return hasAiPart(file);
    return n.prefix ? low.startsWith(want) : low === want;
  });
};

const join = (dir: string, name: string): string =>
  dir === "" ? name : `${dir}/${name}`;

/** Finds the policy files that `reader` gives, at most `FILES_MAX`. */
export const discover = async (reader: Reader): Promise<Found> => {
  const paths: string[] = [];
  const unread: string[] = [];
  const folders: [string, Name[] | undefined][] = [
    ...FOLDERS,
    ...TEMPLATE_FOLDERS.map((d): [string, undefined] => [d, undefined]),
  ];
  for (const [dir, names] of folders) {
    try {
      for (const entry of await reader.list(dir))
        if (
          entry.kind === "file" &&
          (names === undefined || matches(entry.name, names))
        )
          paths.push(join(dir, entry.name));
    } catch {
      // The reader documents no error type, so a failed list is reported by its folder.
      unread.push(dir === "" ? "the root folder" : dir);
    }
  }
  const files: PolicyFile[] = [];
  for (const path of paths.slice(0, FILES_MAX)) {
    try {
      const text = await reader.read(path);
      if (text !== undefined) files.push({ path, text });
    } catch {
      unread.push(path);
    }
  }
  return { files, unread };
};
